#include "sdes.h"
int main(void){int key=0;if(!sd_parse_bits("0111111101",10,&key))return 1;int p[3]={0x01,0x02,0x04};printf("S-DES CTR; key=01111 11101; counter starts at 0000 0000\nPlaintext: ");for(int i=0;i<3;i++){for(int b=7;b>=0;b--)putchar((p[i]>>b)&1?'1':'0');putchar(' ');}int c[3];printf("\nCiphertext: ");for(int i=0;i<3;i++){c[i]=p[i]^sd_encrypt(i,key);for(int b=7;b>=0;b--)putchar((c[i]>>b)&1?'1':'0');putchar(' ');}printf("\nRecovered plaintext: ");for(int i=0;i<3;i++){int back=c[i]^sd_encrypt(i,key);for(int b=7;b>=0;b--)putchar((back>>b)&1?'1':'0');putchar(' ');}puts("\nCTR encrypts the counter block and XORs it with plaintext; decryption uses the same operation.");return 0;}
